// What broke, where, and a link to the failed run — short enough for WhatsApp.
const j = $input.first().json || {};
const ex = j.execution || {};
const wf = j.workflow || {};
const err = ex.error || j.trigger?.error || {};
const node = ex.lastNodeExecuted || err.node?.name || 'unknown step';
const msg = String(err.message || err.description || 'Unknown error').slice(0, 400);
const text = [
  '🚨 *WhatsApp bot error*',
  `Workflow: ${wf.name || wf.id || 'unknown'}`,
  `Step: ${node}`,
  `Error: ${msg}`,
  ex.url ? `Run: ${ex.url}` : null,
  '',
  '_Customers may not be getting replies until this is fixed._',
].filter((l) => l !== null).join('\n');
// The same alert for the inbox: details as a table, the run as a link.
// Turns a WhatsApp card (title line, *Label:* value rows, ━ dividers, a
// "Reply now" link, an _italic_ footer) into an email that reads well in
// Gmail and Outlook: inline styles and tables only.
const toEmail = (text, accent = '#4f46e5', note = '') => {
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const inline = (s) => esc(s)
    .replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" style="color:' + accent + ';text-decoration:none">$1</a>')
    .replace(/\*([^*\n]+)\*/g, '<b>$1</b>').replace(/(^|\s)_([^_\n]+)_(?=\s|$)/g, '$1<i>$2</i>');
  const lines = String(text || '').split('\n');
  const title = lines.shift().replace(/[*_]/g, '').trim();
  let rows = '', body = '', button = '', foot = '';
  for (const raw of lines) {
    const l = raw.trim();
    if (!l || /^━+$/.test(l)) { if (!l && body) body += '<div style="height:8px"></div>'; continue; }
    const reply = l.match(/Reply now:\*?\s*(https?:\/\/\S+)/);
    if (reply) { button = reply[1]; continue; }
    if (/^_.*_$/.test(l)) { foot = l.slice(1, -1); continue; }
    const kv = l.match(/^\*([^*]+):\*\s*(.*)$/);
    if (kv) { rows += '<tr><td style="padding:10px 12px;border-bottom:1px solid #eef0f4;color:#6b7280;font-size:13px;width:34%;vertical-align:top">' + esc(kv[1]) + '</td><td style="padding:10px 12px;border-bottom:1px solid #eef0f4;color:#111827;font-size:14px;font-weight:600;word-break:break-word">' + inline(kv[2]) + '</td></tr>'; continue; }
    // Report figures ("🆕 New contacts: *3*", two may share a line) become table rows too.
    const stats = l.split(' · ').map((p) => p.match(/^([^*:]+):\s*\*([^*]+)\*$/));
    if (stats.every(Boolean)) { for (const m of stats) rows += '<tr><td style="padding:10px 12px;border-bottom:1px solid #eef0f4;color:#374151;font-size:14px">' + esc(m[1].trim()) + '</td><td style="padding:10px 12px;border-bottom:1px solid #eef0f4;color:#111827;font-size:16px;font-weight:700;text-align:right">' + esc(m[2]) + '</td></tr>'; continue; }
    const head = l.match(/^\*([^*]+)\*$/);
    body += head ? '<p style="margin:14px 0 6px;font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:#6b7280;font-weight:700">' + esc(head[1]) + '</p>'
      : '<p style="margin:4px 0;font-size:14px;line-height:1.55;color:#111827">' + inline(l) + '</p>';
  }
  return '<!doctype html><html><body style="margin:0;padding:0;background:#f3f4f6">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6;padding:24px 12px"><tr><td align="center">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:12px;overflow:hidden;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;box-shadow:0 1px 3px rgba(0,0,0,.08)">'
    + '<tr><td style="background:' + accent + ';padding:18px 24px;color:#ffffff;font-size:18px;font-weight:700">' + esc(title) + '</td></tr>'
    + '<tr><td style="padding:20px 24px">'
    + (rows ? '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #eef0f4;border-radius:8px">' + rows + '</table>' : '')
    + body
    + (button ? '<table role="presentation" cellpadding="0" cellspacing="0" style="margin-top:20px"><tr><td style="background:#25d366;border-radius:8px"><a href="' + esc(button) + '" style="display:inline-block;padding:12px 22px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none">Reply on WhatsApp →</a></td></tr></table>' : '')
    + (note ? '<p style="margin:18px 0 0;font-size:13px;color:#6b7280">' + inline(note) + '</p>' : '')
    + '</td></tr>'
    + '<tr><td style="padding:14px 24px;background:#f9fafb;border-top:1px solid #eef0f4;color:#9ca3af;font-size:12px">' + (foot ? esc(foot) + ' · ' : '') + 'Sent by your WhatsApp assistant</td></tr>'
    + '</table></td></tr></table></body></html>';
};
const html = toEmail([
  '🚨 *WhatsApp bot error*',
  `*Workflow:* ${wf.name || wf.id || 'unknown'}`,
  `*Step:* ${node}`,
  `*Error:* ${msg}`,
  ex.url ? `*Failed run:* ${ex.url}` : null,
].filter((l) => l !== null).join('\n'), '#dc2626', 'Customers may not be getting replies until this is fixed.');
return [{ json: { text, html } }];
